import React, { useState, useEffect, useCallback, useRef } from "react";
import Sidebar    from "./Sidebar";
import ChatWindow from "./ChatWindow";
import MobileDrawer from "./MobileDrawer";
import { useAuth }      from "../context/AuthContext";
import { getUserRooms } from "../services/api";
import { wsService }    from "../services/websocket";

export default function ChatApp() {
  const { token, username } = useAuth();
  const [rooms, setRooms]             = useState([]);
  const [activeRoom, setActiveRoom]   = useState(null);
  const [messages, setMessages]       = useState({});       // roomId → msg[]
  const [wsConnected, setWsConnected] = useState(false);
  const [drawerOpen, setDrawerOpen]   = useState(false);

  // Feature: unread counts — roomId → number
  const [unread, setUnread] = useState({});

  const activeRoomRef = useRef(null);
  useEffect(() => { activeRoomRef.current = activeRoom; }, [activeRoom]);

  // Load rooms
  useEffect(() => {
    if (!username) return;
    getUserRooms(username).then(({ data }) => setRooms(data)).catch(() => {});
  }, [username]);

  // Connect WebSocket
  useEffect(() => {
    if (!token) return;
    wsService.connect(token,
      () => {
        setWsConnected(true);
        const room = activeRoomRef.current;
        if (room) {
          wsService.subscribeRoom(room.id, (msg) => handleNewMessage(room.id, [msg], false));
          wsService.subscribeTyping(room.id, () => {}); // kept alive for reconnect
        }
      },
      () => setWsConnected(false)
    );
    return () => wsService.disconnect();
  }, [token]);

  const handleNewMessage = useCallback((roomId, msgs, replace = false) => {
    setMessages((prev) => ({
      ...prev,
      [roomId]: replace ? msgs : dedup([...(prev[roomId] || []), ...msgs]),
    }));

    // Feature: increment unread for rooms that aren't currently open
    if (!replace && activeRoomRef.current?.id !== roomId) {
      setUnread((prev) => ({ ...prev, [roomId]: (prev[roomId] || 0) + msgs.length }));
    }

    // Feature: if this is a reaction update (existing message id already in state),
    // replace that specific message rather than appending
    if (!replace && msgs.length === 1 && msgs[0].id) {
      setMessages((prev) => {
        const existing = prev[roomId] || [];
        const idx = existing.findIndex((m) => m.id === msgs[0].id);
        if (idx === -1) return prev; // new message, already appended above
        const updated = [...existing];
        updated[idx] = msgs[0];
        return { ...prev, [roomId]: updated };
      });
    }
  }, []);

  const handleSelectRoom = (room) => {
    setActiveRoom(room);
    setDrawerOpen(false);
    // Clear unread badge when opening the room
    setUnread((prev) => ({ ...prev, [room.id]: 0 }));
    wsService.subscribeRoom(room.id, (msg) => handleNewMessage(room.id, [msg], false));
    wsService.subscribeTyping(room.id, () => {});
  };

  const handleRoomsChange = (newRoom) => {
    setRooms((prev) => prev.find((r) => r.id === newRoom.id) ? prev : [newRoom, ...prev]);
  };

  return (
    <div className="flex h-full w-full overflow-hidden bg-crisp-bg">
      <div className="hidden lg:flex h-full">
        <Sidebar
          rooms={rooms} activeRoomId={activeRoom?.id}
          onSelectRoom={handleSelectRoom} onRoomsChange={handleRoomsChange}
          wsConnected={wsConnected} messages={messages} unread={unread}
        />
      </div>

      <MobileDrawer open={drawerOpen} onClose={() => setDrawerOpen(false)}>
        <Sidebar
          rooms={rooms} activeRoomId={activeRoom?.id}
          onSelectRoom={handleSelectRoom} onRoomsChange={handleRoomsChange}
          wsConnected={wsConnected} messages={messages} unread={unread}
        />
      </MobileDrawer>

      <main className="flex-1 flex flex-col min-w-0 h-full">
        {/* Mobile bar */}
        <div className="flex items-center gap-3 px-4 py-3 bg-crisp-surface border-b border-crisp-border lg:hidden">
          <button onClick={() => setDrawerOpen(true)}
            className="w-9 h-9 rounded-xl bg-crisp-card border border-crisp-border flex items-center justify-center">
            <svg className="w-5 h-5 text-crisp-sub" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
              <line x1="3" y1="12" x2="21" y2="12"/>
              <line x1="3" y1="6"  x2="21" y2="6"/>
              <line x1="3" y1="18" x2="21" y2="18"/>
            </svg>
          </button>
          <div className="w-8 h-8 bg-crisp-accent rounded-xl flex items-center justify-center font-mono font-bold text-white text-sm">C</div>
          <span className="font-display font-bold text-base text-crisp-text">Crisp</span>
          <span className={`ml-auto w-2 h-2 rounded-full ${wsConnected ? "bg-crisp-green" : "bg-crisp-amber animate-pulse2"}`} />
        </div>

        <ChatWindow
          room={activeRoom}
          messages={activeRoom ? messages[activeRoom.id] : null}
          onNewMessage={handleNewMessage}
          wsConnected={wsConnected}
        />
      </main>
    </div>
  );
}

function dedup(msgs) {
  const seen = new Set();
  return msgs.filter((m) => {
    if (!m.id) return true;
    if (seen.has(m.id)) return false;
    seen.add(m.id);
    return true;
  });
}
